#include "test_common.h"
#include "donation_camp_management.h"
static BmsStatus_t camp_counter(const BmsDonationCamp_t *camp,void *context){CU_ASSERT_PTR_NOT_NULL(camp);(*(uint32_t*)context)++;return BMS_STATUS_OK;}
static void test_add_and_traverse(void){BmsDonationCampContext_t context;BmsDonationCamp_t camp;uint32_t count=0U;memset(&camp,0,sizeof camp);camp.campId=1U;snprintf(camp.name,sizeof camp,"Chennai Blood Donation Camp");camp.date=(BmsDate_t){2026U,8U,15U};snprintf(camp.time,sizeof camp,"09:00");snprintf(camp.venue,sizeof camp,"Community Hall");snprintf(camp.city,sizeof camp,"Chennai");snprintf(camp.organizer,sizeof camp,"Blood Bank Staff");snprintf(camp.contactNumber,sizeof camp,"9876543210");snprintf(camp.email,sizeof camp,"camp@test.com");camp.isActive=true;ASSERT_OK(DonationCampManagementInitialize(&context));ASSERT_OK(DonationCampManagementAdd(&context,&camp));ASSERT_OK(DonationCampManagementTraverse(&context,camp_counter,&count));CU_ASSERT_EQUAL(count,1U);DonationCampManagementDeinitialize(&context);}
void RegisterDonationCampTests(void){CU_pSuite suite=CU_add_suite("Donation Camp",NULL,NULL);CU_add_test(suite,"add and traverse",test_add_and_traverse);}
